"""Aggregate already scored private runs; no paid calls."""
import json,statistics,sys
from pathlib import Path
root=Path(sys.argv[1]);rows=[]
for variant in ['baseline','regions','crops','combined']:
    scores=json.loads((root/variant/'scores.json').read_text())
    rows.append(dict(variant=variant,runs=len(scores),meanIoU=statistics.mean(x['coreIoU'] for x in scores),minimum=min(x['coreIoU'] for x in scores),maximum=max(x['coreIoU'] for x in scores),seconds=statistics.mean(x['seconds'] for x in scores),estimatedUsd=statistics.mean(x['estimatedUsd'] for x in scores)))
(root/'comparison.json').write_text(json.dumps(rows,indent=2));print(json.dumps(rows,indent=2))
total=sum(r['runs']*r['estimatedUsd'] for r in rows)
lines=['# Luna region and crop experiment','', '12 fresh analyses of the supplied apartment. The current pipeline remains the better average result; experimental preprocessing was not promoted to Beta.','', '| Variant | Mean room overlap | Run range | Mean seconds | Estimated cost/run |','|---|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['variant']} | {r['meanIoU']:.1%} | {r['minimum']:.1%}–{r['maximum']:.1%} | {r['seconds']:.1f} | ${r['estimatedUsd']:.5f} |")
lines+=['',f'Estimated total API cost: ${total:.4f}. Usage estimates include both calls and reported cached input/write tokens; these are not billing receipts.','', 'The metric is the existing mean bedroom/hall intersection-over-union, not whole-plan accuracy. The hall score excludes the open entry below source y=755, matching the earlier scorer. Laundry was recognized in one combined run (75.2% overlap), but zero in the other eleven.','', 'Nine numbered connected regions were proposed after directional gap closure. Thin outer boundaries and windows were missed; the hall was divided into artificial pieces. Four crops selected small or irregular candidate regions. Replacing the broad crops reduced coverage. The original remained in every call.','', 'Each variant retained Luna, medium reasoning, two calls, the same token limits, and no answer geometry or apartment-specific room guidance. Variants ran concurrently, with three sequential calls per variant; model/API prompt caching remained enabled. Timing and cost are observations, not controlled performance benchmarks.','', 'Three repeats of one drawing are insufficient for significance or generalization. The detector was adjusted using only the input mask before the paid comparisons. No unseen-plan evaluation was run because this candidate did not pass the development-plan comparison.','', 'Next candidate: preserve broad crops, add limited crops from ambiguous first-pass inventory anchors, and use a wall/door-aware confidence filter before supplying region hypotheses. Do not treat every closed component as a room.','', '## Candidate region overlay','',f'![Numbered candidate regions]({(root/"regions-overlay.jpg").as_posix()})']
(root/'report.md').write_text('\n'.join(lines),encoding='utf-8')
print(f'Total estimated USD: {total:.6f}')
